#include "scarlett_imports64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m; ScarlettImports64 im; assert(im.install(m)); constexpr uint64_t p=0x10000; assert(m.map(p,4096,3)==GuestMemory64::Fault::none);uint64_t r=0;auto call=[&](const char*n,uint64_t a=0x10000,uint64_t spin=0){auto f=im.registerImport("api-ms-win-core-synch-l1-1-0.dll",n);assert(f);return im.dispatch(f,m,a,r,spin);};auto read=[&](unsigned off){std::array<uint8_t,4>b{};assert(m.read(p+off,b)==GuestMemory64::Fault::none);return uint32_t(b[0])|(uint32_t(b[1])<<8)|(uint32_t(b[2])<<16)|(uint32_t(b[3])<<24);};assert(call("InitializeCriticalSectionAndSpinCount",p,4000)&&r==1&&read(8)==UINT32_MAX&&read(32)==4000);assert(call("EnterCriticalSection")&&read(12)==1&&read(16)==1);assert(call("TryEnterCriticalSection")&&r==1&&read(12)==2);assert(!call("DeleteCriticalSection"));assert(call("LeaveCriticalSection")&&call("LeaveCriticalSection")&&read(12)==0&&read(16)==0);assert(!call("LeaveCriticalSection"));assert(call("DeleteCriticalSection"));assert(!call("EnterCriticalSection"));assert(!call("InitializeCriticalSection",p+4096));assert(call("InitializeCriticalSection"));std::cout<<"V16 synchronization tests passed\n";}
